{"path":"game/main.gd","content":"extends Node2D

const BallScene = preload("res://game/ball.tscn")
const PaddlePath = "Paddle"

signal game_over

var score:int = 0
var lives:int = 3
var state:String = "playing"

onready var spawn_timer:Timer = $SpawnTimer
onready var score_label:Label = $HUD/ScoreLabel
onready var lives_label:Label = $HUD/LivesLabel
onready var paddle_node = get_node(PaddlePath)

func _ready() -> void:
    # Ensure window title
    if Engine.has_singleton("OS"):
        OS.window_title = "Bounce Catch"
    # Input actions
    if not InputMap.has_action("move_left"):
        InputMap.add_action("move_left")
    var ev = InputEventKey.new()
    ev.physical_keycode = Key.LEFT
    InputMap.action_add_event("move_left", ev)

    if not InputMap.has_action("move_right"):
        InputMap.add_action("move_right")
    var ev2 = InputEventKey.new()
    ev2.physical_keycode = Key.RIGHT
    InputMap.action_add_event("move_right", ev2)

    if not InputMap.has_action("restart"):
        InputMap.add_action("restart")
    var ev3 = InputEventKey.new()
    ev3.physical_keycode = Key.R
    InputMap.action_add_event("restart", ev3)

    if not InputMap.has_action("quit"):
        InputMap.add_action("quit")
    var ev4 = InputEventKey.new()
    ev4.physical_keycode = Key.ESCAPE
    InputMap.action_add_event("quit", ev4)

    # Connect spawn timer
    spawn_timer.connect("timeout", Callable(self, "spawn_ball"))
    # Start fresh
    reset_game()

func spawn_ball() -> void:
    if state != "playing":
        return
    var ball = BallScene.instantiate()
    # Random x at top
    var rng = RandomNumberGenerator.new()
    rng.randomize()
    var x = rng.randi_range(32, 800 - 32)
    ball.position = Vector2(x, -16)
    add_child(ball)
    # Connect signals; pass the ball as extra argument
    if ball.has_signal("bounced"):
        ball.connect("bounced", Callable(self, "_on_ball_bounced"), [ball])
    if ball.has_signal("missed"):
        ball.connect("missed", Callable(self, "_on_ball_missed"), [ball])

func _on_ball_bounced(ball_ref: Node) -> void:
    if state != "playing":
        return
    score += 1
    score_label.text = "Score: %d" % score
    if score >= 15:
        state = "win"
        print("WIN %d" % score)
        # stop spawning
        spawn_timer.stop()

func _on_ball_missed(ball_ref: Node) -> void:
    # Remove the ball node safely
    if is_instance_valid(ball_ref):
        ball_ref.queue_free()
    if state != "playing":
        return
    lives -= 1
    lives_label.text = "Lives: %d" % lives
    if lives <= 0:
        state = "game_over"
        print("GAME OVER %d" % score)
        spawn_timer.stop()

func _process(delta: float) -> void:
    # Handle restart and quit input
    if Input.is_action_just_pressed("restart") and state != "playing":
        reset_game()
    if Input.is_action_just_pressed("quit"):
        get_tree().quit()

func reset_game() -> void:
    # Remove existing balls
    for child in get_children():
        if child is Node and child.filename == "res://game/ball.tscn":
            # unlikely; safer by name check
            pass
    # Instead, remove nodes that have the 'bounced' signal (balls)
    var to_remove: Array = []
    for c in get_children():
        if c.has_method("is_ball"):
            to_remove.append(c)
    for b in to_remove:
        if is_instance_valid(b):
            b.queue_free()
    score = 0
    lives = 3
    state = "playing"
    score_label.text = "Score: %d" % score
    lives_label.text = "Lives: %d" % lives
    spawn_timer.start()
